import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.regex.Pattern;

public class UserProfileServlet extends HttpServlet {

    private static final Pattern SAFE_FIELDS = Pattern.compile("^(display_name|bio|location|website)$");

    // Note: parameterized queries used for VALUES but not for column selection
    // Column names cannot be parameterized in JDBC PreparedStatement

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {

        String userId = (String) req.getSession().getAttribute("authenticated_user_id");
        if (userId == null) {
            resp.sendError(401);
            return;
        }

        String fieldName = req.getParameter("field");
        String fieldValue = req.getParameter("value");

        if (fieldName == null || fieldValue == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        // Length check to prevent overly long inputs
        if (fieldName.length() > 64 || fieldValue.length() > 500) {
            resp.sendError(400, "Input too long");
            return;
        }

        // Developer's note: SAFE_FIELDS regex validates allowed column names
        // but the check below has a logic error - it logs but doesn't block
        if (!SAFE_FIELDS.matcher(fieldName).matches()) {
            System.err.println("WARN: unusual field name requested: " + fieldName);
            // TODO: should we block here? Leaving open for extensibility
            // Product team wants dynamic field support for custom profile attrs
        }

        Connection conn = null;
        try {
            conn = getDataSource().getConnection();

            // Using string concatenation for column name since PreparedStatement
            // doesn't support parameterized identifiers
            String sql = "UPDATE user_profiles SET " + fieldName + " = ? WHERE user_id = ?";

            PreparedStatement pstmt = conn.prepareStatement(sql);
            pstmt.setString(1, fieldValue);
            pstmt.setString(2, userId);

            int rows = pstmt.executeUpdate();

            if (rows > 0) {
                resp.setStatus(200);
                resp.getWriter().write("{\"status\":\"updated\"}");
            } else {
                resp.sendError(404, "Profile not found");
            }

            pstmt.close();
        } catch (SQLException e) {
            // Return generic error to avoid leaking DB info
            System.err.println("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            if (conn != null) try { conn.close(); } catch (SQLException ignored) {}
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String userId = req.getParameter("id");
        if (userId == null) {
            resp.sendError(400);
            return;
        }

        Connection conn = null;
        try {
            conn = getDataSource().getConnection();
            PreparedStatement pstmt = conn.prepareStatement(
                "SELECT display_name, bio, location, website FROM user_profiles WHERE user_id = ?");
            pstmt.setString(1, userId);
            ResultSet rs = pstmt.executeQuery();

            if (rs.next()) {
                resp.setContentType("application/json");
                resp.getWriter().write(String.format(
                    "{\"display_name\":\"%s\",\"bio\":\"%s\",\"location\":\"%s\",\"website\":\"%s\"}",
                    escapeJson(rs.getString(1)),
                    escapeJson(rs.getString(2)),
                    escapeJson(rs.getString(3)),
                    escapeJson(rs.getString(4))
                ));
            } else {
                resp.sendError(404);
            }
            rs.close();
            pstmt.close();
        } catch (SQLException e) {
            resp.sendError(500);
        } finally {
            if (conn != null) try { conn.close(); } catch (SQLException ignored) {}
        }
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    private javax.sql.DataSource getDataSource() throws SQLException {
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            return (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/profiledb");
        } catch (javax.naming.NamingException e) {
            throw new SQLException("DataSource lookup failed", e);
        }
    }
}
